namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "English", Code = "ENG", Description = "Study of literature, writing, and rhetoric." },
        new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has authored two textbooks on Python programming.", IsFeatured = true },
        new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming).", Credits = 4, Schedule = "TTh 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park's research focuses on algorithm optimization. He holds a PhD from MIT and has published extensively on graph algorithms.", IsFeatured = true },
        new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, indexing, and transaction processing. Includes a semester-long project building a full database application.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked as a database architect at Oracle for 10 years before joining academia. She specializes in distributed database systems." },
        new() { Id = 4, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator who has developed innovative approaches to teaching calculus through visualization.", IsFeatured = true },
        new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "MATH 220", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "TTh 2:00–3:15 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson researches applications of linear algebra in machine learning and has collaborated with industry partners on AI projects." },
        new() { Id = 6, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "ENG 101", Title = "College Writing", Description = "Develop critical reading and writing skills through essay composition, peer review, and revision workshops.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", InstructorName = "Prof. David Brown", InstructorBio = "Prof. Brown is a published novelist and essayist who brings creative writing techniques into academic composition instruction." },
        new() { Id = 7, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, democracy, and social change.", Credits = 3, Schedule = "TTh 11:00 AM–12:15 PM", InstructorName = "Dr. Angela Rivera", InstructorBio = "Dr. Rivera specializes in 20th-century American fiction and has published a critical study of Toni Morrison's novels.", IsFeatured = true },
        new() { Id = 8, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with weekly lab sessions.", Credits = 4, Schedule = "MWF 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is an experimental physicist whose research on fluid dynamics has been featured in Nature and Science." },
        new() { Id = 9, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "PHYS 201", Title = "Electricity and Magnetism", Description = "Electric fields, magnetic fields, circuits, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "TTh 9:00–10:15 AM + Lab Wed 2:00–4:50 PM", InstructorName = "Dr. Lisa Nakamura", InstructorBio = "Dr. Nakamura's work in quantum electrodynamics has earned her multiple NSF grants and a university teaching excellence award." },
        new() { Id = 10, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory to 1500 CE, covering Mesopotamia, Egypt, Greece, Rome, China, and the Islamic world.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is an archaeologist and historian who has directed excavations in the Mediterranean and published on ancient trade networks." },
        new() { Id = 11, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "HIST 320", Title = "The Civil Rights Movement", Description = "In-depth study of the American civil rights movement from 1954 to 1975, examining key figures, organizations, and legislative changes.", Credits = 3, Schedule = "TTh 1:00–2:15 PM", InstructorName = "Dr. Patricia Moore", InstructorBio = "Dr. Moore has spent her career documenting oral histories of civil rights activists and advises the Smithsonian's National Museum of African American History.", IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return GetCourse(request.CourseId) is not null
            && !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId);
    }
}

